<?php
require_once dirname(__DIR__).'/includes/functions.php';require_content_manager();verify_csrf();$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$company=trim($_POST['company']??'');$location=trim($_POST['location']??'');$type=$_POST['employment_type']??'';$description=trim($_POST['description']??'');$requirements=trim($_POST['requirements']??'');$closing=trim($_POST['closing_date']??'');$career=(int)($_POST['career_id']??0);$active=isset($_POST['is_active'])?1:0;$types=['internship','learnership','part_time','full_time','contract'];
if(!$title||!$company||!$description||!in_array($type,$types,true))json_response(['ok'=>false,'message'=>'Title, company, opportunity type, and description are required.'],422);if($closing&&DateTime::createFromFormat('Y-m-d',$closing)===false)json_response(['ok'=>false,'message'=>'Choose a valid closing date.'],422);$closingValue=$closing?:null;$careerValue=$career?:null;
try{if($id){$stmt=$con->prepare('UPDATE job_opportunities SET career_id=?,title=?,company=?,location=?,employment_type=?,description=?,requirements=?,closing_date=?,is_active=? WHERE id=?');$stmt->bind_param('isssssssii',$careerValue,$title,$company,$location,$type,$description,$requirements,$closingValue,$active,$id);$action='update';}else{$creator=(int)user()['id'];$stmt=$con->prepare('INSERT INTO job_opportunities(career_id,title,company,location,employment_type,description,requirements,closing_date,is_active,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$stmt->bind_param('isssssssii',$careerValue,$title,$company,$location,$type,$description,$requirements,$closingValue,$active,$creator);$action='create';}$stmt->execute();$id=$id?:$con->insert_id;admin_log($con,$action,'job_opportunity',$id,$title.' at '.$company);json_response(['ok'=>true,'message'=>'Job opportunity saved.','reload'=>true]);}catch(Throwable $e){error_log('Job save error: '.$e->getMessage());json_response(['ok'=>false,'message'=>'The opportunity could not be saved.'],500);}
